import { describe, it, expect, beforeEach } from 'vitest';

// Test suite for rgba color validation and opacity specification
// Verifies that code adaptations preserve existing functionality and enforce
// security requirements around rgba color usage with opacity specifications

describe('rgba color validation and opacity enforcement', () => {
  describe('rgba detection', () => {
    it('should identify rgba values in CSS color strings', () => {
      const rgbaRegex = /rgba\s*\(\s*\d+\s*,\s*\d+\s*,\s*\d+\s*,\s*[\d.]+\s*\)/i;
      expect('rgba(255, 0, 0, 1)').toMatch(rgbaRegex);
      expect('rgba(100, 150, 200, 0.5)').toMatch(rgbaRegex);
      expect('rgb(255, 0, 0)').not.toMatch(rgbaRegex);
    });

    it('should validate rgba with opacity between 0 and 1', () => {
      const validRgbaWithOpacity = [
        'rgba(255, 0, 0, 0)',
        'rgba(255, 0, 0, 0.5)',
        'rgba(255, 0, 0, 1)',
        'rgba(100, 150, 200, 0.25)'
      ];
      validRgbaWithOpacity.forEach(color => {
        expect(color).toMatch(/rgba\s*\(\s*\d+\s*,\s*\d+\s*,\s*\d+\s*,\s*[\d.]+\s*\)/);
      });
    });
  });

  describe('opacity specification validation', () => {
    it('should reject rgba without opacity value', () => {
      const rgbaWithoutOpacityRegex = /rgba\s*\(\s*\d+\s*,\s*\d+\s*,\s*\d+\s*\)(?!\s*,|\s*\/)/;
      expect('rgba(255, 0, 0)').toMatch(rgbaWithoutOpacityRegex);
      expect('rgba(100, 150, 200)').toMatch(rgbaWithoutOpacityRegex);
    });

    it('should enforce that rgba always includes 4 parameters', () => {
      const validateRgbaOpacity = (color) => {
        const match = color.match(/rgba\s*\(([^)]+)\)/);
        if (!match) return false;
        const params = match[1].split(',').map(p => p.trim()).filter(p => p.length > 0);
        return params.length === 4;
      };

      expect(validateRgbaOpacity('rgba(255, 0, 0, 1)')).toBe(true);
      expect(validateRgbaOpacity('rgba(255, 0, 0)')).toBe(false);
      expect(validateRgbaOpacity('rgba(255, 0, 0, 0.5, extra)')).toBe(true); // matches first 4
    });

    it('should validate opacity parameter is numeric', () => {
      const validateOpacityIsNumeric = (color) => {
        const match = color.match(/rgba\s*\(\s*\d+\s*,\s*\d+\s*,\s*\d+\s*,\s*([\d.]+)\s*\)/);
        return match ? !isNaN(parseFloat(match[1])) : false;
      };

      expect(validateOpacityIsNumeric('rgba(255, 0, 0, 0.5)')).toBe(true);
      expect(validateOpacityIsNumeric('rgba(255, 0, 0, 1)')).toBe(true);
      expect(validateOpacityIsNumeric('rgba(255, 0, 0, invalid)')).toBe(false);
    });
  });

  describe('preserve existing functionality', () => {
    it('should not modify valid rgba colors with opacity', () => {
      const originalColor = 'rgba(255, 0, 0, 0.8)';
      const processedColor = originalColor; // No modification for valid colors
      expect(processedColor).toEqual(originalColor);
    });

    it('should not interfere with non-rgba color formats', () => {
      const colors = ['#ff0000', 'red', 'rgb(255, 0, 0)', 'hsl(0, 100%, 50%)'];
      colors.forEach(color => {
        expect(color).not.toMatch(/rgba\s*\(.*,.*,.*,.*\)/);
      });
    });

    it('should preserve color channel values (0-255)', () => {
      const validateChannels = (color) => {
        const match = color.match(/rgba\s*\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)\s*,\s*[\d.]+\s*\)/);
        if (!match) return false;
        const [, r, g, b] = match.map(Number);
        return [r, g, b].every(c => c >= 0 && c <= 255);
      };

      expect(validateChannels('rgba(255, 0, 0, 1)')).toBe(true);
      expect(validateChannels('rgba(100, 150, 200, 0.5)')).toBe(true);
      expect(validateChannels('rgba(256, 0, 0, 1)')).toBe(false);
    });
  });

  describe('security: opacity specification enforcement', () => {
    it('should flag rgba colors missing opacity as security risk', () => {
      const insecureColors = ['rgba(255, 0, 0)', 'rgba(100, 150, 200)'];
      const hasOpacity = (color) => /rgba\s*\(\s*\d+\s*,\s*\d+\s*,\s*\d+\s*,\s*[\d.]+\s*\)/.test(color);

      insecureColors.forEach(color => {
        expect(hasOpacity(color)).toBe(false);
      });
    });

    it('should require explicit opacity to prevent color override attacks', () => {
      const requiresExplicitOpacity = (color) => {
        // Rgba without opacity could be overridden by style injection
        return /rgba\s*\(\s*\d+\s*,\s*\d+\s*,\s*\d+\s*,\s*[\d.]+\s*\)/.test(color);
      };

      // Secure: explicit opacity specified
      expect(requiresExplicitOpacity('rgba(255, 0, 0, 1)')).toBe(true);
      // Insecure: no opacity value
      expect(requiresExplicitOpacity('rgba(255, 0, 0)')).toBe(false);
    });

    it('should allow opacity range 0-1 to prevent invalid specifications', () => {
      const isValidOpacity = (opacity) => {
        const num = parseFloat(opacity);
        return !isNaN(num) && num >= 0 && num <= 1;
      };

      expect(isValidOpacity('0')).toBe(true);
      expect(isValidOpacity('0.5')).toBe(true);
      expect(isValidOpacity('1')).toBe(true);
      expect(isValidOpacity('1.5')).toBe(false);
      expect(isValidOpacity('-0.1')).toBe(false);
    });
  });

  describe('edge cases and error handling', () => {
    it('should handle whitespace variations in rgba syntax', () => {
      const normalizeAndValidate = (color) => {
        return /rgba\s*\(\s*\d+\s*,\s*\d+\s*,\s*\d+\s*,\s*[\d.]+\s*\)/.test(color);
      };

      expect(normalizeAndValidate('rgba(255, 0, 0, 1)')).toBe(true);
      expect(normalizeAndValidate('rgba( 255 , 0 , 0 , 1 )')).toBe(true);
      expect(normalizeAndValidate('rgba(255,0,0,1)')).toBe(true);
    });

    it('should handle rgba with decimal channel values gracefully', () => {
      // Most implementations convert to 0-255 range
      const validateChannels = (color) => {
        const match = color.match(/rgba\s*\(\s*([\d.]+)\s*,\s*([\d.]+)\s*,\s*([\d.]+)\s*,\s*([\d.]+)\s*\)/);
        if (!match) return false;
        const values = match.slice(1).map(Number);
        return values.length === 4 && !values.some(isNaN);
      };

      expect(validateChannels('rgba(255.5, 100.2, 50.8, 0.5)')).toBe(true);
    });

    it('should not break on empty or null values', () => {
      const safeValidate = (color) => {
        if (!color || color.length === 0) return false;
        return /rgba\s*\(\s*\d+\s*,\s*\d+\s*,\s*\d+\s*,\s*[\d.]+\s*\)/.test(color);
      };

      expect(safeValidate('')).toBe(false);
      expect(safeValidate(null)).toBe(false);
      expect(safeValidate('rgba(255, 0, 0, 0.5)')).toBe(true);
    });
  });

  describe('code adaptation and reuse validation', () => {
    it('should preserve validation logic from prior implementations', () => {
      // Ensures adapted code maintains original security checks
      const originalValidator = (color) => {
        return /rgba\s*\(\s*\d+\s*,\s*\d+\s*,\s*\d+\s*,\s*[\d.]+\s*\)/.test(color);
      };

      // Adapted code should have same behavior
      const adaptedValidator = (color) => {
        return /rgba\s*\(\s*\d+\s*,\s*\d+\s*,\s*\d+\s*,\s*[\d.]+\s*\)/.test(color);
      };

      const testColors = ['rgba(255, 0, 0, 1)', 'rgba(255, 0, 0)', '#ff0000', 'rgb(255, 0, 0)'];
      testColors.forEach(color => {
        expect(adaptedValidator(color)).toEqual(originalValidator(color));
      });
    });
  });
});
